ProductCard.css:
.mapsvg-product-simple {
  --ms-text: #111;
  --ms-muted: #8a8a8e;
  --ms-desc: #5c5c62;
  --ms-line: #e4e4ea;
  --ms-bg: #fff;
  --ms-accent: #5c5890;
  --ms-accent-hover: #4f4b7e;
  --ms-grad-from: #c4c0ff;
  --ms-grad-to: #6b6698;
  --ms-btn-radius: 12px;

  background: var(--ms-bg);
  overflow: hidden;
  color: var(--ms-text);
  font-family: var(--mapsvg-font-family, Helvetica, Arial, sans-serif);
  -webkit-font-smoothing: antialiased;
  width: 100%;
}

.mapsvg-product-gallery {
  position: relative;
  margin: 0;
  padding: 0;
  height: fit-content;
  display: block;
  overflow: hidden;
}

.mapsvg-product-image {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
}

.mapsvg-product-body {
  padding: 10px 20px 20px 15px;
}

.mapsvg-product-title {
  margin: 0 0 10px;
  font-size: 1.35rem;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.mapsvg-product-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0 0 12px;
}

.mapsvg-product-badge {
  display: inline-block;
  padding: 3px 8px;
  border: 1px solid var(--ms-line);
  border-radius: 6px;
  color: var(--ms-muted);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1.4;
}

.mapsvg-product-excerpt {
  margin: 0 0 18px;
  color: var(--ms-desc);
  font-size: 0.92rem;
  line-height: 1.55;
}

.mapsvg-product-excerpt p {
  margin: 0;
}

.mapsvg-product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.mapsvg-product-price-wrap {
  flex: 0 0 auto;
  min-width: 0;
}

.mapsvg-product-price-label {
  display: block;
  margin: 0 0 2px;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ms-muted);
}

.mapsvg-product-price {
  margin: 0;
  font-size: 1.25rem;
  line-height: 1.2;
  font-weight: 700;
  color: var(--ms-text);
}

.mapsvg-product-price del {
  color: var(--ms-muted);
  font-weight: 500;
  font-size: 0.85em;
  margin-right: 0.35em;
}

.mapsvg-product-price ins {
  text-decoration: none;
  color: var(--ms-text);
  font-weight: 700;
}

.mapsvg-product-price .amount {
  white-space: nowrap;
}

.mapsvg-product-cart {
  flex: 1 1 auto;
  margin: 0;
  max-width: 62%;
}

.mapsvg-product-cart form.cart {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0;
  margin: 0;
}

.mapsvg-product-cart .quantity,
.mapsvg-product-cart input.qty {
  display: none !important;
}

.mapsvg-product-cart button,
.mapsvg-product-cart .single_add_to_cart_button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45em;
  width: 100%;
  min-height: 46px;
  border: 0;
  border-radius: var(--ms-btn-radius);
  padding: 0 18px;
  background: var(--ms-accent);
  color: #fff !important;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  white-space: nowrap;
  line-height: 1;
}

.mapsvg-product-cart button svg,
.mapsvg-product-cart .single_add_to_cart_button svg {
  display: block;
  flex-shrink: 0;
  width: 1.15em;
  height: 1.15em;
  stroke: currentColor;
}

.mapsvg-product-cart button:hover,
.mapsvg-product-cart .single_add_to_cart_button:hover {
  background: var(--ms-accent-hover);
}

.mapsvg-product-cart-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 46px;
  border-radius: var(--ms-btn-radius);
  padding: 0 18px;
  background: var(--ms-accent);
  color: #fff !important;
  font-size: 0.95rem;
  font-weight: 600;
  text-decoration: none !important;
}

.mapsvg-product-cart-link:hover {
  background: var(--ms-accent-hover);
  color: #fff !important;
}
